// Validate and normalize deploy request
const body = $input.first().json.body || $input.first().json;

const storyId = body.story_id;
const environment = body.environment || 'preview';
const trigger = body.trigger || 'manual';
const force = body.force === true;
const appName = body.app_name || null; // optional; used by post-deploy WF_PLAYWRIGHT_RUN chain to resolve B/G slot URL
const playwrightSuite = body.playwright_suite || 'all';
const playwrightOptIn = body.playwright !== false; // default: run; caller can disable per-deploy

if (!storyId) {
  throw new Error('Missing story_id in deploy request');
}

return [{
  json: {
    story_id: storyId,
    environment,
    trigger,
    force,
    app_name: appName,
    playwright_suite: playwrightSuite,
    playwright_opt_in: playwrightOptIn,
    requested_at: new Date().toISOString()
  }
}];

// Build success report
const deploy = $input.first().json;
const input = $('Validate Input').item.json;

return [{
  json: {
    status: 'success',
    story_id: input.story_id,
    environment: input.environment,
    provider: deploy.provider,
    duration_ms: deploy.duration_ms,
    message: deploy.message,
    trigger: input.trigger,
    completed_at: new Date().toISOString()
  }
}];

// Chain into WF_PLAYWRIGHT_RUN after a successful staging deploy.
// Skips silently when: not staging, opt-out flag set, or no app_name was passed.
// Soft-fails so a Playwright outage cannot mask a deploy success.
const input = $('Validate Input').item.json;
const success = $('Log Success').item.json;
const envIsStaging = (input.environment || '').toLowerCase() === 'staging';
const shouldRun = envIsStaging && input.playwright_opt_in === true && input.app_name;
if (!shouldRun) {
  return [{ json: { ...success, playwright: { skipped: true, reason: !envIsStaging ? 'not_staging' : !input.playwright_opt_in ? 'opted_out' : 'no_app_name' } } }];
}
const n8nBase = $env.N8N_WEBHOOK_URL || 'http://n8n:5678';
const webhookPath = `${n8nBase.replace(/\/$/, '')}/webhook/playwright-run`;
try {
  const res = await fetch(webhookPath, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      trigger_kind: 'staging_auto',
      target_env: 'staging',
      target_base_url: 'auto',
      app_name: input.app_name,
      story_id: input.story_id,
      suite: input.playwright_suite || 'all',
      deploy_ref: success.provider ? String(success.provider) : null,
      metadata: {
        source: 'WF_DEPLOY_STORY',
        provider: success.provider || null,
        deploy_duration_ms: success.duration_ms || null,
        trigger: success.trigger || input.trigger || null
      }
    })
  });
  if (!res.ok) {
    const text = await res.text();
    return [{ json: { ...success, playwright: { skipped: false, ok: false, status: res.status, body: text.slice(0, 400) } } }];
  }
  const j = await res.json().catch(() => ({}));
  return [{ json: { ...success, playwright: { skipped: false, ok: true, run_id: j.run_id || null, approval_required: !!j.approval_required } } }];
} catch (e) {
  return [{ json: { ...success, playwright: { skipped: false, ok: false, error: e.message } } }];
}
